content:
[
  {
    "tag": "痛点共鸣",
    "prompt": "你是小红书爆款文案专家。围绕{目标人群}在{场景}中最大的痛点，写3个开头钩子，每个不超过30字，用第二人称直击痛点并制造好奇，输出为编号列表。",
    "usage": "美妆、职场、育儿等赛道用痛点引发共鸣时",
    "example": "1. 每天化妆2小时，下午就斑驳脱妆？你可能忽略了这一步。"
  },
  {
    "tag": "数字冲击",
    "prompt": "你是小红书标题高手。用具体数字为{产品/方法}写5个开头钩子，突出{核心效果}，例如时间、金额、人数，每个20字以内，要求数字真实可信、有对比感，输出编号列表。",
    "usage": "干货分享、好物推荐需要数据背书时",
    "example": "1. 坚持这3个动作，我30天瘦了8斤没反弹。"
  },
  {
    "tag": "反差反转",
    "prompt": "你是小红书文案策划。以{身份/物品}为切入点，写4个制造反差的开头钩子，先抛出常规认知再反转，每个不超过35字，语气口语化，输出为编号列表。",
    "usage": "打破刻板印象、制造记忆点时",
    "example": "1. 月薪3千的我，靠这招住进了月租8千的房子。"
  },
  {
    "tag": "悬念提问",
    "prompt": "你是小红书开头钩子专家。围绕{话题}设计5个提问式钩子，问题要让人忍不住想点开找答案，避免常识性问题，每个25字以内，输出编号列表并附一句答案悬念提示。",
    "usage": "知识科普、经验分享类笔记开头",
    "example": "1. 为什么你越护肤皮肤越差？答案和你想的相反。"
  },
  {
    "tag": "身份标签",
    "prompt": "你是小红书运营专家。为{特定身份人群}撰写4个开头钩子，用身份标签+专属利益点结构，让目标用户觉得"说的就是我"，每个30字以内，输出编号列表。",
    "usage": "垂直人群精准引流，如宝妈、考研党、打工人",
    "example": "1. 打工人必看：这5个摸鱼技巧让我准点下班还被夸。"
  },
  {
    "tag": "时间紧迫",
    "prompt": "你是小红书文案高手。为{内容主题}写4个带时间压力的开头钩子，使用"3天""一周""现在"等时间词制造紧迫感，承诺明确结果，每个25字以内，输出编号列表。",
    "usage": "教程、挑战、限时活动类内容",
    "example": "1. 只需7天，用这个方法把杂乱衣柜整理成样板间。"
  },
  {
    "tag": "对比反差",
    "prompt": "你是小红书爆款开头设计师。围绕{前后变化场景}写4个对比式钩子，用"以前…现在…"或"别人…我…"句式，突出{核心改变}，每个35字以内，输出编号列表。",
    "usage": "减肥、改造、逆袭类笔记开头",
    "example": "1. 以前拍照只敢站最后，现在朋友都问我是不是整容了。"
  },
  {
    "tag": "避坑警告",
    "prompt": "你是小红书干货博主。为{领域}写5个避坑式开头钩子，用"千万别""别再""踩过才知道"等警示语开头，点出{常见错误}，每个30字以内，输出编号列表。",
    "usage": "测评、攻略、新手教程类内容引流",
    "example": "1. 千万别这样敷面膜，我烂脸半年才知道原因。"
  },
  {
    "tag": "情绪故事",
    "prompt": "你是小红书情感文案专家。以{情绪关键词}为基调，为{故事主题}写3个故事化开头钩子，第一句就制造情绪张力，用第一人称，每个40字以内，输出编号列表。",
    "usage": "情感、成长、生活记录类笔记开头",
    "example": "1. 被裁员那天我笑着走出公司，回家却在电梯里哭了。"
  },
  {
    "tag": "稀缺福利",
    "prompt": "你是小红书福利帖文案专家。为{资源/福利}写4个突出稀缺性的开头钩子，强调"限量""私藏""很少有人知道"，每个25字以内，避免夸张违规词，输出编号列表。",
    "usage": "资料分享、隐藏好物、小众资源类笔记",
    "example": "1. 这个免费网站我私藏了3年，今天终于舍得分享。"
  }
]
